1	import fs from 'node:fs';
2	import path from 'node:path';
3	import {isDeepStrictEqual as same} from 'node:util';
4	import {applyDelta} from '../../lib/journal.mjs';
5	
6	// Read-only reconstruction. Callers save desired snapshots outside the authority,
7	// read the real drafts, and submit changes through a fresh CLI record-template.
8	export function replaySnapshots(work,state){
9	 const snapshots=[structuredClone(state.baseline)];
10	 for(const unit of state.units){const journal=JSON.parse(fs.readFileSync(path.join(work,unit.journal),'utf8'));snapshots.push(applyDelta(structuredClone(snapshots.at(-1)),journal.patch));}
11	 if(!same(snapshots.at(-1),state.snapshot))throw Error('Journal reconstruction differs from authority');
12	 return snapshots;
13	}
14	export function changesBetween(before,after,unit){
15	 if(!same(before.timeline,after.timeline.slice(0,before.timeline.length)))throw Error(`Historical timeline changed within unit ${unit}; correct desired snapshots consistently, never overwrite authority`);
16	 const changes={characters:{},timeline_append:after.timeline.slice(before.timeline.length),ledger:{}};
17	 for(const [name,value] of Object.entries(after.characters))if(!same(before.characters[name],value))changes.characters[name]=value;
18	 const retired=Object.keys(before.characters).filter(x=>!Object.hasOwn(after.characters,x));if(retired.length)changes.retire_characters=retired;
19	 if(!same(before.threads,after.threads))changes.threads=after.threads;
20	 for(const id of Object.keys(before.ledger??{}))if(!Object.hasOwn(after.ledger??{},id))throw Error(`Ledger removed: ${id}`);
21	 for(const [id,value] of Object.entries(after.ledger??{})){
22	  const previous=before.ledger?.[id]??{},delta={};
23	  for(const name of Object.keys(previous.character_known??{}))if(!Object.hasOwn(value.character_known??{},name))throw Error(`Knowledge field removed: ${id}.${name}`);
24	  for(const [key,item] of Object.entries(value)){
25	   if(['evidence','introduced_unit','updated_unit'].includes(key)||same(previous[key],item))continue;
26	   if(key==='character_known')delta[key]=Object.fromEntries(Object.entries(item).filter(([name,text])=>!same(previous[key]?.[name],text)));
27	   else delta[key]=structuredClone(item);
28	  }
29	  const anchors=(value.evidence??[]).filter(e=>e.unit===unit).map(e=>({unit:e.unit,quote:e.quote}));
30	  if(anchors.length)delta.evidence=anchors;
31	  if(Object.keys(delta).length){
32	   if(!anchors.length)throw Error(`Changed ledger has no current-unit evidence: ${unit}:${id}`);
33	   if(delta.custody&&previous.custody&&delta.custody.holder!==previous.custody.holder)delta.previous_holder=previous.custody.holder;
34	   changes.ledger[id]=delta;
35	  }
36	 }
37	 return changes;
38	}
